				new Image(Asset.getAssetFilePath(GeneralAsset.ETHEREAL_CHAIN)),
				new Callback() {
			public void call() {
				Actor.add(new Pushing(hero, hero.pos, newHeroPos, new Callback() {
					public void call() {
