public abstract class Level implements Bundlable {

	public static enum Feeling {
		NONE,
		CHASM,
		WATER,
		GRASS,
		DARK,
		LARGE,
		TRAPS,
		SECRETS
	}

	protected int width;
	protected int height;
	protected int length;

	protected static final float TIME_TO_RESPAWN	= 50;

	public int version;

	public int[] map;
	public boolean[] visited;
	public boolean[] mapped;
	public boolean[] discoverable;

	public int viewDistance = Dungeon.isChallenged( Challenges.DARKNESS ) ? 2 : 8;

	public boolean[] heroFOV;

	public boolean[] passable;
	public boolean[] losBlocking;
	public boolean[] flamable;
	public boolean[] secret;
	public boolean[] solid;
	public boolean[] avoid;
	public boolean[] water;
	public boolean[] pit;

	public boolean[] openSpace;

	public Feeling feeling = Feeling.NONE;

	public ArrayList<LevelTransition> transitions;

	//when a boss level has become locked.
	public boolean locked = false;

	public HashSet<Mob> mobs;
	public SparseArray<Heap> heaps;
	public HashMap<Class<? extends Blob>,Blob> blobs;
	public SparseArray<Plant> plants;
	public SparseArray<Trap> traps;
	public HashSet<CustomTilemap> customTiles;
	public HashSet<CustomTilemap> customWalls;

	protected ArrayList<Item> itemsToSpawn = new ArrayList<>();

	protected Group visuals;

	public int color1 = 0x004400;
	public int color2 = 0x88CC44;

	private static final String VERSION     = "version";
	private static final String WIDTH       = "width";
	private static final String HEIGHT      = "height";
	private static final String MAP			= "map";
	private static final String VISITED		= "visited";
	private static final String MAPPED		= "mapped";
	private static final String TRANSITIONS	= "transitions";
	private static final String LOCKED      = "locked";
	private static final String HEAPS		= "heaps";
	private static final String PLANTS		= "plants";
	private static final String TRAPS       = "traps";
	private static final String CUSTOM_TILES= "customTiles";
	private static final String CUSTOM_WALLS= "customWalls";
	private static final String MOBS		= "mobs";
	private static final String BLOBS		= "blobs";
	private static final String FEELING		= "feeling";

	public void create() {

		Random.pushGenerator( Dungeon.seedCurDepth() );

		if (!(Dungeon.bossLevel())) {

			addItemToSpawn(Generator.random(Generator.Category.FOOD));

			if (Dungeon.isChallenged(Challenges.DARKNESS)){
				addItemToSpawn( new Torch() );
			}

			if (Arrays.asList(Dungeon.posLevels).contains(Dungeon.levelName)) {
				addItemToSpawn( new PotionOfStrength() );
			}
			if (Arrays.asList(Dungeon.souLevels).contains(Dungeon.levelName)) {
				addItemToSpawn( new ScrollOfUpgrade() );
			}
			if (Arrays.asList(Dungeon.asLevels).contains(Dungeon.levelName)) {
				addItemToSpawn( new Stylus() );
			}
			//one scroll of transmutation is guaranteed to spawn somewhere on chapter 2-4
			int enchChapter = (int)((Dungeon.seed / 10) % 3) + 1;
			if ( Dungeon.depth / 5 == enchChapter &&
					Dungeon.seed % 4 + 1 == Dungeon.depth % 5){
				addItemToSpawn( new StoneOfEnchantment() );
			}

			if ( Dungeon.depth == ((Dungeon.seed % 3) + 1)){
				addItemToSpawn( new StoneOfIntuition() );
			}

			switch (Dungeon.layout.getDungeon().get(Dungeon.levelName).getLevelFeeling()) {
				case "random":
					if (Dungeon.depth > 1) {
						//50% chance of getting a level feeling
						//~7.15% chance for each feeling
						switch (Random.Int( 14 )) {
							case 0:
								feeling = Feeling.CHASM;
								break;
							case 1:
								feeling = Feeling.WATER;
								break;
							case 2:
								feeling = Feeling.GRASS;
								break;
							case 3:
								feeling = Feeling.DARK;
								addItemToSpawn(new Torch());
								viewDistance = Math.round(viewDistance/2f);
								break;
							case 4:
								feeling = Feeling.LARGE;
								addItemToSpawn(Generator.random(Generator.Category.FOOD));
								//add a second torch to help with the larger floor
								if (Dungeon.isChallenged(Challenges.DARKNESS)){
									addItemToSpawn( new Torch() );
								}
								break;
							case 5:
								feeling = Feeling.TRAPS;
								break;
							case 6:
								feeling = Feeling.SECRETS;
								break;
						}
					}
					break;
				case "chasm":
					feeling = Feeling.CHASM;
					break;
				case "water":
					feeling = Feeling.WATER;
					break;
				case "grass":
					feeling = Feeling.GRASS;
					break;
				case "dark":
					feeling = Feeling.DARK;
					break;
				case "large":
					feeling = Feeling.LARGE;
					break;
				case "traps":
					feeling = Feeling.TRAPS;
					break;
				case "secrets":
					feeling = Feeling.SECRETS;
					break;
			}
		}

		do {
			width = height = length = 0;

			transitions = new ArrayList<>();

			mobs = new HashSet<>();
			heaps = new SparseArray<>();
			blobs = new HashMap<>();
			plants = new SparseArray<>();
			traps = new SparseArray<>();
			customTiles = new HashSet<>();
			customWalls = new HashSet<>();

		} while (!build());

		buildFlagMaps();
		cleanWalls();

		createMobs();
		createItems();

		switch (Dungeon.layout.getDungeon().get(Dungeon.levelName).getVisibility()) {
			case ONLY_VISIBLE:
				for (int i=0; i < length; i++) {
					if (discoverable[i]) {
						visited[i] = true;
					}
				}
				GameScene.updateFog();
				break;
			case SECRETS:
				for (int i=0; i < length; i++) {
					int terr = map[i];
					if (discoverable[i]) {
						visited[i] = true;
						if ((Terrain.flags[terr] & Terrain.SECRET) != 0) {
							discover( i );
						}
					}
				}
				GameScene.updateFog();
				break;
		}

		Random.popGenerator();
	}

	public void setSize(int w, int h){

		width = w;
		height = h;
		length = w * h;

		map = new int[length];
		Arrays.fill( map, feeling == Level.Feeling.CHASM ? Terrain.CHASM : Terrain.WALL );

		visited     = new boolean[length];
		mapped      = new boolean[length];

		heroFOV     = new boolean[length];

		passable	= new boolean[length];
		losBlocking	= new boolean[length];
		flamable	= new boolean[length];
		secret		= new boolean[length];
		solid		= new boolean[length];
		avoid		= new boolean[length];
		water		= new boolean[length];
		pit			= new boolean[length];

		openSpace   = new boolean[length];

		PathFinder.setMapSize(w, h);
	}

	public void reset() {

		for (Mob mob : mobs.toArray( new Mob[0] )) {
			if (!mob.reset()) {
				mobs.remove( mob );
			}
		}
		createMobs();
	}

	public void playLevelMusic(){
		//do nothing by default
	}

	@Override
	public void restoreFromBundle( Bundle bundle ) {

		version = bundle.getInt( VERSION );

		//saves from before this version are not supported
		if (version < ShatteredPixelDungeon.LAST_SUPPORTED_SAVES_VERSION){
			throw new RuntimeException("old save");
		}

		setSize( bundle.getInt(WIDTH), bundle.getInt(HEIGHT));

		mobs = new HashSet<>();
		heaps = new SparseArray<>();
		blobs = new HashMap<>();
		plants = new SparseArray<>();
		traps = new SparseArray<>();
		customTiles = new HashSet<>();
		customWalls = new HashSet<>();

		map		= bundle.getIntArray( MAP );

		visited	= bundle.getBooleanArray( VISITED );
		mapped	= bundle.getBooleanArray( MAPPED );

		transitions = new ArrayList<>();
		for (Bundlable b : bundle.getCollection( TRANSITIONS )){
			transitions.add((LevelTransition) b);
		}

		locked      = bundle.getBoolean( LOCKED );

		Collection<Bundlable> collection = bundle.getCollection( HEAPS );
		for (Bundlable h : collection) {
			Heap heap = (Heap)h;
			if (!heap.isEmpty())
				heaps.put( heap.pos, heap );
		}

		collection = bundle.getCollection( PLANTS );
		for (Bundlable p : collection) {
			Plant plant = (Plant)p;
			plants.put( plant.pos, plant );
		}

		collection = bundle.getCollection( TRAPS );
		for (Bundlable p : collection) {
			Trap trap = (Trap)p;
			traps.put( trap.pos, trap );
		}

		collection = bundle.getCollection( CUSTOM_TILES );
		for (Bundlable p : collection) {
			CustomTilemap vis = (CustomTilemap)p;
			customTiles.add(vis);
		}

		collection = bundle.getCollection( CUSTOM_WALLS );
		for (Bundlable p : collection) {
			CustomTilemap vis = (CustomTilemap)p;
			customWalls.add(vis);
		}

		collection = bundle.getCollection( MOBS );
		for (Bundlable m : collection) {
			Mob mob = (Mob)m;
			if (mob != null) {
				mobs.add( mob );
			}
		}

		collection = bundle.getCollection( BLOBS );
		for (Bundlable b : collection) {
			Blob blob = (Blob)b;
			blobs.put( blob.getClass(), blob );
		}

		feeling = bundle.getEnum( FEELING, Feeling.class );
		if (feeling == Feeling.DARK)
			viewDistance = Math.round(viewDistance/2f);

		if (bundle.contains( "mobs_to_spawn" )) {
			for (Class<? extends Mob> mob : bundle.getClassArray("mobs_to_spawn")) {
				if (mob != null) mobsToSpawn.add(mob);
			}
		}

		if (bundle.contains( "custom_mobs_to_spawn" )) {
