public class WndRanking extends WndTabbed {

	private static final int WIDTH			= 115;
	private static final int HEIGHT			= 144;

	private static WndRanking INSTANCE;

	private String gameID;
	private Rankings.Record record;

	public WndRanking( final Rankings.Record rec ) {

		super();
		resize( WIDTH, HEIGHT );

		if (INSTANCE != null){
			INSTANCE.hide();
		}
		INSTANCE = this;

		this.gameID = rec.gameID;
		this.record = rec;

		try {
			Badges.loadGlobal();
			Rankings.INSTANCE.loadGameData( rec );
			createControls();
		} catch ( Exception e ) {
			Game.reportException( new RuntimeException("Rankings Display Failed!",e));
			Dungeon.hero = null;
			createControls();
		}
	}

	@Override
	public void destroy() {
		super.destroy();
		if (INSTANCE == this){
			INSTANCE = null;
		}
	}

	private void createControls() {

		if (Dungeon.hero != null) {
			Image[] icons = {
				new Image(Asset.getAssetFilePath(GeneralAsset.ICON_RANKINGS)),
				new Image(Asset.getAssetFilePath(GeneralAsset.ICON_TALENT)),
				new Image(Asset.getAssetFilePath(GeneralAsset.ICON_BACKPACK_LRG)),
				new Image(Asset.getAssetFilePath(GeneralAsset.ICON_BADGES)),
				new Image(Asset.getAssetFilePath(GeneralAsset.ICON_CHALLENGE_ON))
			};
			Group[] pages =
					{new StatsTab(), new TalentsTab(), new ItemsTab(), new BadgesTab(), null};

			if (Dungeon.challenges != 0) pages[4] = new ChallengesTab();

			for (int i = 0; i < pages.length; i++) {

				if (pages[i] == null) {
					break;
				}

				add(pages[i]);

				Tab tab = new RankingTab(icons[i], pages[i]);
				add(tab);
			}

			layoutTabs();

			select(0);
		} else {
			StatsTab tab = new StatsTab();
			add(tab);

		}
	}

