	public void execute( Hero hero, String action ) {

		GameScene.cancel();
		curUser = hero;
		curItem = this;

		if (action.equals( AC_DROP )) {

			if (hero.belongings.backpack.contains(this) || isEquipped(hero)) {
				doDrop(hero);
			}

		} else if (action.equals( AC_THROW )) {

			if (hero.belongings.backpack.contains(this) || isEquipped(hero)) {
				doThrow(hero);
			}

		}
	}

