	@Override
	public int mobLimit() {
		if (Dungeon.depth <= 1){
			if (!Statistics.amuletObtained) return 0;
			else                            return 10;
		}

		int mobs = 3 + Dungeon.depth % 5 + Random.Int(3);
		if (feeling == Feeling.LARGE){
			mobs = (int)Math.ceil(mobs * 1.33f);
		}
		return mobs;
	}

	@Override
	protected void createMobs() {

		super.createMobs();

		//on floor 1, 8 pre-set mobs are created so the player can get level 2.
		int mobsToSpawn = Dungeon.depth == 1 ? 8 : mobLimit();

		ArrayList<Room> stdRooms = new ArrayList<>();
		for (Room room : rooms) {
			if (room instanceof StandardRoom && room != roomEntrance) {
				for (int i = 0; i < ((StandardRoom) room).sizeCat.roomValue; i++) {
					stdRooms.add(room);
				}
			}
		}
		Random.shuffle(stdRooms);
		Iterator<Room> stdRoomIter = stdRooms.iterator();

		while (mobsToSpawn > 0) {
			Mob mob = createMob();
			Room roomToSpawn;

			if (!stdRoomIter.hasNext()) {
				stdRoomIter = stdRooms.iterator();
			}
			roomToSpawn = stdRoomIter.next();

			int tries = 30;
			do {
				mob.pos = pointToCell(roomToSpawn.random());
				tries--;
			} while (tries >= 0 && (findMob(mob.pos) != null
					|| !passable[mob.pos]
					|| solid[mob.pos]
					|| !roomToSpawn.canPlaceCharacter(cellToPoint(mob.pos), this)
					|| mob.pos == exit()
					|| traps.get(mob.pos) != null || plants.get(mob.pos) != null
					|| (!openSpace[mob.pos] && mob.properties().contains(Char.Property.LARGE))));

			if (tries >= 0) {
				mobsToSpawn--;
				mobs.add(mob);

				//chance to add a second mob to this room, except on floor 1
				if (Dungeon.depth > 1 && mobsToSpawn > 0 && Random.Int(4) == 0){
					mob = createMob();

					tries = 30;
					do {
						mob.pos = pointToCell(roomToSpawn.random());
						tries--;
					} while (tries >= 0 && (findMob(mob.pos) != null
							|| !passable[mob.pos]
							|| solid[mob.pos]
							|| !roomToSpawn.canPlaceCharacter(cellToPoint(mob.pos), this)
							|| mob.pos == exit()
							|| traps.get(mob.pos) != null || plants.get(mob.pos) != null
							|| (!openSpace[mob.pos] && mob.properties().contains(Char.Property.LARGE))));

					if (tries >= 0) {
						mobsToSpawn--;
						mobs.add(mob);
					}
				}
			}
		}

		for (ExtraMobSpawn mobSpawn : Dungeon.layout.getDungeon().get(Dungeon.levelName).getExtraMobs()) {
			Mob mob = (Mob) Reflection.newInstance(Reflection.forName("com.qsr.customspd.actors.mobs." + mobSpawn.getType()));
			if (mobSpawn.getAlignment() != null) mob.alignment = Char.Alignment.valueOf(mobSpawn.getAlignment().toUpperCase(Locale.ENGLISH));
			if (mobSpawn.getHp() != null) {
				mob.HP = mobSpawn.getHp();
			}
			if (mobSpawn.getChampion() != null) {
				Buff.affect(mob, Reflection.forName("com.qsr.customspd.actors.buffs.ChampionEnemy$" + mobSpawn.getChampion()));
			}
			if (mobSpawn.getAiState() != null) {
				switch (mobSpawn.getAiState().toUpperCase()) {
					case "SLEEPING":
						mob.state = mob.SLEEPING;
						break;
					case "HUNTING":
						mob.state = mob.HUNTING;
						break;
					case "WANDERING":
						mob.state = mob.WANDERING;
						break;
					case "FLEEING":
						mob.state = mob.FLEEING;
						break;
					case "PASSIVE":
						mob.state = mob.PASSIVE;
						break;
				}
			}

			Room roomToSpawn;

			if (!stdRoomIter.hasNext()) {
				stdRoomIter = stdRooms.iterator();
			}
			roomToSpawn = stdRoomIter.next();

			int tries = 30;
			do {
				mob.pos = pointToCell(roomToSpawn.random());
				tries--;
			} while (tries >= 0 && (findMob(mob.pos) != null
				|| !passable[mob.pos]
				|| solid[mob.pos]
				|| !roomToSpawn.canPlaceCharacter(cellToPoint(mob.pos), this)
				|| mob.pos == exit()
				|| (!openSpace[mob.pos] && mob.properties().contains(Char.Property.LARGE))));

			if (tries >= 0) {
				mobs.add(mob);
			}
		}

		for (Mob m : mobs){
			if (map[m.pos] == Terrain.HIGH_GRASS || map[m.pos] == Terrain.FURROWED_GRASS) {
				map[m.pos] = Terrain.GRASS;
				losBlocking[m.pos] = false;
			}

		}

	}

	@Override
	public int randomRespawnCell( Char ch ) {
		int count = 0;
		int cell = -1;

		while (true) {

			if (++count > 30) {
				return -1;
			}

			Room room = randomRoom( StandardRoom.class );
			if (room == null || room == roomEntrance) {
				continue;
			}

			cell = pointToCell(room.random(1));
			if (!heroFOV[cell]
					&& Actor.findChar( cell ) == null
					&& passable[cell]
					&& !solid[cell]
					&& (!Char.hasProp(ch, Char.Property.LARGE) || openSpace[cell])
					&& room.canPlaceCharacter(cellToPoint(cell), this)
					&& cell != exit()) {
				return cell;
			}

		}
	}

	@Override
	public int randomDestination( Char ch ) {

		int count = 0;
		int cell = -1;

		while (true) {

			if (++count > 30) {
				return -1;
			}

			Room room = Random.element( rooms );
			if (room == null) {
				continue;
			}

			ArrayList<Point> points = room.charPlaceablePoints(this);
			if (!points.isEmpty()){
				cell = pointToCell(Random.element(points));
				if (passable[cell] && (!Char.hasProp(ch, Char.Property.LARGE) || openSpace[cell])) {
					return cell;
				}
			}

		}
	}

	@Override
	protected void createItems() {

		// drops 3/4/5 items 60%/30%/10% of the time
		int nItems = 3 + Random.chances(new float[]{6, 3, 1});

		if (feeling == Feeling.LARGE){
			nItems += 2;
		}

		for (int i=0; i < nItems; i++) {

			Item toDrop = Generator.random();
			if (toDrop == null) continue;

			int cell = randomDropCell();
			if (map[cell] == Terrain.HIGH_GRASS || map[cell] == Terrain.FURROWED_GRASS) {
				map[cell] = Terrain.GRASS;
				losBlocking[cell] = false;
			}

			Heap.Type type = null;
			switch (Random.Int( 20 )) {
			case 0:
				type = Heap.Type.SKELETON;
				break;
			case 1:
			case 2:
			case 3:
			case 4:
				type = Heap.Type.CHEST;
				break;
			case 5:
				if (Dungeon.depth > 1 && findMob(cell) == null){
					mobs.add(Mimic.spawnAt(cell, toDrop));
					continue;
				}
				type = Heap.Type.CHEST;
				break;
			default:
				type = Heap.Type.HEAP;
				break;
			}

			if ((toDrop instanceof Artifact && Random.Int(2) == 0) ||
					(toDrop.isUpgradable() && Random.Int(4 - toDrop.level()) == 0)){

				if (Dungeon.depth > 1 && Random.Int(10) == 0 && findMob(cell) == null){
					mobs.add(Mimic.spawnAt(cell, toDrop, GoldenMimic.class));
				} else {
					Heap dropped = drop(toDrop, cell);
					if (heaps.get(cell) == dropped) {
						dropped.type = Heap.Type.LOCKED_CHEST;
						addItemToSpawn(new GoldenKey(Dungeon.levelName));
					}
				}
			} else {
				Heap dropped = drop( toDrop, cell );
				dropped.type = type;
				if (type == Heap.Type.SKELETON){
					dropped.setHauntedIfCursed();
				}
			}

		}

		for (ExtraItemSpawn itemSpawn : Dungeon.layout.getDungeon().get(Dungeon.levelName).getExtraItems()) {
			int pos = randomDropCell();
			Item item;
			try {
				Generator.Category category = Generator.Category.valueOf(itemSpawn.getCategory());
				if (itemSpawn.getIgnoreDeck()) {
					item = Generator.randomUsingDefaults(category);
				} else {
					item = Generator.random(category);
				}
			} catch (IllegalArgumentException | NullPointerException e) {
				if (itemSpawn.getType().equals("weapon.missiles.darts.TippedDart")) {
					item = TippedDart.randomTipped(1);
				} else {
					item = (Item) Reflection.newInstance(Reflection.forName("com.qsr.customspd.items." + itemSpawn.getType()));
				}
			}
			if (itemSpawn.getSeal() && item instanceof Armor) ((Armor)item).affixSeal(new BrokenSeal());
			if (itemSpawn.getCoreWand() != null && item instanceof MagesStaff) item = new MagesStaff((Wand) Reflection.newInstance(Reflection.forName("com.qsr.customspd.items." + itemSpawn.getCoreWand())));
			item.quantity(itemSpawn.getQuantity());
			if (itemSpawn.getQuantityMin() != null && itemSpawn.getQuantityMax() != null) {
				item.quantity(Random.IntRange(itemSpawn.getQuantityMin(), itemSpawn.getQuantityMax()));
			}
			item.level(itemSpawn.getLevel());
			if (itemSpawn.getIdentified()) {
				item.identify(itemSpawn.getHeapType() == null || Heap.Type.valueOf(itemSpawn.getHeapType()) != Heap.Type.FOR_SALE);
			}
			if (Boolean.TRUE.equals(itemSpawn.getCursed())) item.cursed = true;
			if (Boolean.FALSE.equals(itemSpawn.getCursed())) item.cursed = false;
			if (itemSpawn.getEnchantment() != null) {
				if (item instanceof Armor) {
					if (itemSpawn.getEnchantment().equals("none")) {
						((Armor) item).inscribe(null);
					} else {
						((Armor) item).inscribe((Armor.Glyph) Reflection.newInstance(Reflection.forName("com.qsr.customspd.items.armor." + itemSpawn.getEnchantment())));
					}
				} else if (item instanceof Weapon) {
					if (itemSpawn.getEnchantment().equals("none")) {
						((Weapon) item).enchant(null);
					} else {
						((Weapon) item).enchant((Weapon.Enchantment) Reflection.newInstance(Reflection.forName("com.qsr.customspd.items.weapon." + itemSpawn.getEnchantment())));
					}
				}
			}
			if (item instanceof Key) {
				if (itemSpawn.getLevelName() == null) {
					((Key) item).levelName = Dungeon.levelName;
				} else {
					((Key) item).levelName = itemSpawn.getLevelName();
				}
			}
			Heap dropped = drop(item, pos);
			if (itemSpawn.getHeapType() != null) {
				Heap.Type type = Heap.Type.valueOf(itemSpawn.getHeapType());
				dropped.type = type;
				if (type == Heap.Type.SKELETON){
					dropped.setHauntedIfCursed();
				}
			}
			if (map[pos] == Terrain.HIGH_GRASS || map[pos] == Terrain.FURROWED_GRASS) {
				map[pos] = Terrain.GRASS;
				losBlocking[pos] = false;
			}
		}

		for (Item item : itemsToSpawn) {
			int cell = randomDropCell();
			drop( item, cell ).type = Heap.Type.HEAP;
			if (map[cell] == Terrain.HIGH_GRASS || map[cell] == Terrain.FURROWED_GRASS) {
				map[cell] = Terrain.GRASS;
				losBlocking[cell] = false;
			}
		}

		//use a separate generator for this to prevent held items, meta progress, and talents from affecting levelgen
		//we can use a random long for the seed as it will be the same long every time
		Random.pushGenerator( Random.Long() );

		Item item = Bones.get();
		if (item != null) {
			int cell = randomDropCell();
			if (map[cell] == Terrain.HIGH_GRASS || map[cell] == Terrain.FURROWED_GRASS) {
				map[cell] = Terrain.GRASS;
				losBlocking[cell] = false;
			}
			drop( item, cell ).setHauntedIfCursed().type = Heap.Type.REMAINS;
		}

		DriedRose rose = Dungeon.hero.belongings.getItem( DriedRose.class );
		if (rose != null && rose.isIdentified() && !rose.cursed && Ghost.Quest.completed()){
			//aim to drop 1 petal every 2 floors
			int petalsNeeded = (int) Math.ceil((float)((Dungeon.depth / 2) - rose.droppedPetals) / 3);

			for (int i=1; i <= petalsNeeded; i++) {
				//the player may miss a single petal and still max their rose.
				if (rose.droppedPetals < 11) {
					item = new DriedRose.Petal();
					int cell = randomDropCell();
					drop( item, cell ).type = Heap.Type.HEAP;
					if (map[cell] == Terrain.HIGH_GRASS || map[cell] == Terrain.FURROWED_GRASS) {
						map[cell] = Terrain.GRASS;
						losBlocking[cell] = false;
					}
					rose.droppedPetals++;
				}
			}
		}

		//cached rations try to drop in a special room on floors 2/3/4/6/7/8, to a max of 4/6
		if (Dungeon.hero.hasTalent(Talent.CACHED_RATIONS)){
			Talent.CachedRationsDropped dropped = Buff.affect(Dungeon.hero, Talent.CachedRationsDropped.class);
			if (dropped.count() < 2 + 2*Dungeon.hero.pointsInTalent(Talent.CACHED_RATIONS)){
				int cell;
				int tries = 100;
				boolean valid;
				do {
					cell = randomDropCell(SpecialRoom.class);
					valid = cell != -1 && !(room(cell) instanceof SecretRoom)
							&& !(room(cell) instanceof ShopRoom)
							&& map[cell] != Terrain.EMPTY_SP
							&& map[cell] != Terrain.WATER
							&& map[cell] != Terrain.PEDESTAL;
 				} while (tries-- > 0 && !valid);
				if (valid) {
					if (map[cell] == Terrain.HIGH_GRASS || map[cell] == Terrain.FURROWED_GRASS) {
						map[cell] = Terrain.GRASS;
						losBlocking[cell] = false;
					}
					drop(new SmallRation(), cell).type = Heap.Type.CHEST;
					dropped.countUp(1);
				}
			}
		}

		//guide pages
		Collection<String> allPages = Document.ADVENTURERS_GUIDE.pageNames();
		ArrayList<String> missingPages = new ArrayList<>();
		for ( String page : allPages){
			if (!Document.ADVENTURERS_GUIDE.isPageFound(page)){
				missingPages.add(page);
			}
		}

		//a total of 6 pages drop randomly, the rest are specially dropped or are given at the start
		missingPages.remove(Document.GUIDE_SEARCHING);

		//chance to find a page is 0/25/50/75/100% for floors 1/2/3/4/5+
		float dropChance = 0.25f*(Dungeon.depth-1);
		if (!missingPages.isEmpty() && Random.Float() < dropChance){
			GuidePage p = new GuidePage();
			p.page(missingPages.get(0));
			int cell = randomDropCell();
			if (map[cell] == Terrain.HIGH_GRASS || map[cell] == Terrain.FURROWED_GRASS) {
				map[cell] = Terrain.GRASS;
				losBlocking[cell] = false;
			}
			drop( p, cell );
		}

		//lore pages
		//TODO a fair bit going on here, I might want to refactor/externalize this in the future
		if (Document.ADVENTURERS_GUIDE.allPagesFound()){

			int region = 1+(Dungeon.depth-1)/5;

			Document regionDoc;
			switch( region ){
				default: regionDoc = null; break;
				case 1: regionDoc = Document.SEWERS_GUARD; break;
				case 2: regionDoc = Document.PRISON_WARDEN; break;
				case 3: regionDoc = Document.CAVES_EXPLORER; break;
				case 4: regionDoc = Document.CITY_WARLOCK; break;
				case 5: regionDoc = Document.HALLS_KING; break;
			}

			if (regionDoc != null && !regionDoc.allPagesFound()) {

				Dungeon.LimitedDrops limit = limitedDocs.get(regionDoc);

				if (limit == null || !limit.dropped()) {

					float totalPages = 0;
					float pagesFound = 0;
					String pageToDrop = null;
					for (String page : regionDoc.pageNames()) {
						totalPages++;
						if (!regionDoc.isPageFound(page)) {
							if (pageToDrop == null) {
								pageToDrop = page;
							}
						} else {
							pagesFound++;
						}
					}
					float percentComplete = pagesFound / totalPages;

					// initial value is the first floor in a region
					int targetFloor = 5*(region-1) + 1;
					targetFloor += Math.round(3*percentComplete);

					//TODO maybe drop last page in boss floor with custom logic?
					if (Dungeon.depth >= targetFloor){
						DocumentPage page = RegionLorePage.pageForDoc(regionDoc);
						page.page(pageToDrop);
						int cell = randomDropCell();
						if (map[cell] == Terrain.HIGH_GRASS || map[cell] == Terrain.FURROWED_GRASS) {
							map[cell] = Terrain.GRASS;
							losBlocking[cell] = false;
						}
						drop(page, cell);
						if (limit != null) limit.drop();
					}

				}

			}

		}

		Random.popGenerator();

	}

	private static HashMap<Document, Dungeon.LimitedDrops> limitedDocs = new HashMap<>();
	static {
		limitedDocs.put(Document.SEWERS_GUARD, Dungeon.LimitedDrops.LORE_SEWERS);
		limitedDocs.put(Document.PRISON_WARDEN, Dungeon.LimitedDrops.LORE_PRISON);
		limitedDocs.put(Document.CAVES_EXPLORER, Dungeon.LimitedDrops.LORE_CAVES);
		limitedDocs.put(Document.CITY_WARLOCK, Dungeon.LimitedDrops.LORE_CITY);
		limitedDocs.put(Document.HALLS_KING, Dungeon.LimitedDrops.LORE_HALLS);
	}

	public ArrayList<Room> rooms() {
		return new ArrayList<>(rooms);
	}

	protected Room randomRoom( Class<?extends Room> type ) {
		Random.shuffle( rooms );
		for (Room r : rooms) {
			if (type.isInstance(r)) {
				return r;
			}
		}
		return null;
	}

	public Room room( int pos ) {
		for (Room room : rooms) {
			if (room.inside( cellToPoint(pos) )) {
				return room;
			}
		}

		return null;
	}

	protected int randomDropCell(){
		return randomDropCell(StandardRoom.class);
	}

	protected int randomDropCell( Class<?extends Room> roomType ) {
		int tries = 100;
		while (tries-- > 0) {
			Room room = randomRoom( roomType );
			if (room == null){
				return -1;
			}
			if (room != roomEntrance) {
				int pos = pointToCell(room.random());
				if (passable[pos] && !solid[pos]
						&& pos != exit()
						&& heaps.get(pos) == null
						&& room.canPlaceItem(cellToPoint(pos), this)
						&& findMob(pos) == null) {

					Trap t = traps.get(pos);

					//items cannot spawn on traps which destroy items
					if (t == null ||
							! (t instanceof BurningTrap || t instanceof BlazingTrap
							|| t instanceof ChillingTrap || t instanceof FrostTrap
							|| t instanceof ExplosiveTrap || t instanceof DisintegrationTrap
							|| t instanceof PitfallTrap)) {

						return pos;
					}
				}
			}
		}
		return -1;
	}

	@Override
	public int fallCell( boolean fallIntoPit ) {
		if (fallIntoPit) {
			for (Room room : rooms) {
				if (room instanceof PitRoom) {
					ArrayList<Integer> candidates = new ArrayList<>();
					for (Point p : room.getPoints()){
						int cell = pointToCell(p);
						if (passable[cell] &&
								findMob(cell) == null){
							candidates.add(cell);
						}
					}

					if (!candidates.isEmpty()){
						return Random.element(candidates);
					}
				}
			}
		}

		return super.fallCell( fallIntoPit );
	}

