	@Override
	public void occupyCell(Char ch) {
		if (ch == Dungeon.hero){
			switch (state){
				case START:
					if (cellToPoint(ch.pos).y > tenguCell.top){
						progress();
					}
					break;
				case FIGHT_PAUSE:

					if (cellToPoint(ch.pos).y <= startHallway.top+1){
						progress();
					}
					break;
			}
		}

		super.occupyCell(ch);
	}

