		for (Room.Door door : connected.values()) {
			door.set( Room.Door.Type.REGULAR );
		}

		Point c = center();

		Painter.fill( level, c.x-1, c.y-1, 3, 2, Terrain.WALL );
		Painter.fill( level, c.x-1, c.y+1, 3, 1, Terrain.EMPTY_SP );

