		Painter.set( level, exitCell, Terrain.LOCKED_EXIT );
		LevelTransition exit = new LevelTransition(level, exitCell, LevelTransition.Type.REGULAR_EXIT, 0);
		exit.top--;
		exit.left--;
		exit.right++;
		level.transitions.add(exit);

		CustomTilemap vis = new SewerExit();
		vis.pos(c.x-1, c.y);
		level.customTiles.add(vis);

		vis = new SewerExitOverhang();
		vis.pos(c.x-1, c.y-2);
		level.customWalls.add(vis);

