							if (ch == Dungeon.hero){
								Statistics.qualifiedForBossChallengeBadge = false;
								Statistics.bossScores[1] -= 100;
							}

							if (Dungeon.level.flamable[cell]){
								Dungeon.level.destroy( cell );

